package sqlite

// schema defines the only supported storage format. No migrations are applied.
const schema = `CREATE TABLE administrators(id INTEGER PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,password_hash BLOB NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,administrator_id INTEGER NOT NULL REFERENCES administrators(id),expires_at INTEGER NOT NULL);
CREATE TABLE tmdb_cache(key TEXT PRIMARY KEY,value BLOB NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE rule_chain(id TEXT PRIMARY KEY CHECK(id='current'));
CREATE TABLE config(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE CHECK(id='1'),f_version INTEGER NOT NULL,f_source_root TEXT NOT NULL,f_target_root TEXT NOT NULL,f_token TEXT NOT NULL,f_proxy_url TEXT NOT NULL,f_language TEXT NOT NULL,f_rules_movie_folder TEXT NOT NULL,f_rules_movie_file TEXT NOT NULL,f_rules_tv_folder TEXT NOT NULL,f_rules_tv_file TEXT NOT NULL);
CREATE TABLE config_categories(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_type TEXT NOT NULL,f_year_min INTEGER NOT NULL,f_year_max INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES config(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES config(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX config_categories_root ON config_categories(root);
CREATE TABLE category_countries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES config_categories(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES config(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX category_countries_root ON category_countries(root);
CREATE TABLE category_genres(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES config_categories(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES config(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX category_genres_root ON category_genres(root);
CREATE TABLE rules(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_id TEXT NOT NULL,f_name TEXT NOT NULL,f_description TEXT NOT NULL,f_target TEXT NOT NULL,f_source TEXT NOT NULL,f_order INTEGER NOT NULL,f_enabled INTEGER NOT NULL,f_kind TEXT NOT NULL,f_stage TEXT NOT NULL,f_config_code TEXT NOT NULL,f_config_params TEXT,f_config_pattern TEXT NOT NULL,f_config_capture TEXT NOT NULL,f_config_value TEXT,FOREIGN KEY(owner) REFERENCES rule_chain(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES rule_chain(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX rules_root ON rules(root);
CREATE TABLE rule_examples(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_root TEXT NOT NULL,f_expected TEXT,FOREIGN KEY(owner) REFERENCES rules(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES rule_chain(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE TABLE rule_examples_paths(owner TEXT NOT NULL REFERENCES rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE TABLE rule_examples_targets(owner TEXT NOT NULL REFERENCES rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE INDEX rule_examples_root ON rule_examples(root);
CREATE TABLE recognitions(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_revision INTEGER NOT NULL,f_state TEXT NOT NULL,f_completed INTEGER NOT NULL,f_total INTEGER NOT NULL,f_error TEXT NOT NULL,f_created TEXT NOT NULL,f_purpose TEXT NOT NULL CHECK(f_purpose IN ('organize','scrape')));
CREATE TABLE workspace_paths(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES recognitions(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX workspace_paths_root ON workspace_paths(root);
CREATE TABLE workspace_items(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_path TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_season INTEGER NOT NULL,f_group TEXT NOT NULL,f_state TEXT NOT NULL,f_reason TEXT NOT NULL,f_selected INTEGER NOT NULL,f_removed INTEGER NOT NULL,f_edited INTEGER NOT NULL,f_trace_id TEXT NOT NULL,f_identity TEXT NOT NULL,f_work_dir TEXT NOT NULL,f_season_dir TEXT NOT NULL,f_movie_prefix INTEGER NOT NULL,f_layout_manual INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES recognitions(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX workspace_items_root ON workspace_items(root);
CREATE TABLE workspace_confirmations(owner TEXT PRIMARY KEY REFERENCES workspace_items(k) ON DELETE CASCADE,root TEXT NOT NULL REFERENCES recognitions(id) ON DELETE CASCADE,f_source TEXT NOT NULL,f_at TEXT NOT NULL,f_identity TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_type TEXT NOT NULL,f_tmdbid INTEGER NOT NULL,f_season INTEGER NOT NULL,f_basis_kind TEXT NOT NULL,f_trace_id TEXT NOT NULL,f_candidate_id TEXT NOT NULL,f_source_id TEXT NOT NULL,f_digit_index INTEGER NOT NULL,f_pattern TEXT NOT NULL,f_offset INTEGER NOT NULL);
CREATE TABLE confirmation_episodes(owner TEXT NOT NULL REFERENCES workspace_confirmations(owner) ON DELETE CASCADE,position INTEGER NOT NULL,value INTEGER NOT NULL,PRIMARY KEY(owner,position));
CREATE TABLE item_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES workspace_items(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_episodes_root ON item_episodes(root);
CREATE TABLE metadata_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES item_metadata(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX metadata_episodes_root ON metadata_episodes(root);
CREATE TABLE trace_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES trace_metadata(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX trace_episodes_root ON trace_episodes(root);
CREATE TABLE mapping_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES media_mappings(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES media_mappings(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX mapping_episodes_root ON mapping_episodes(root);
CREATE TABLE run_mapping_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES run_mappings(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX run_mapping_episodes_root ON run_mapping_episodes(root);
CREATE TABLE item_metadata(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_tmdbid INTEGER,f_title TEXT,f_media_type TEXT,f_year INTEGER,f_season INTEGER,FOREIGN KEY(owner) REFERENCES workspace_items(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_metadata_root ON item_metadata(root);
CREATE TABLE trace_metadata(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_tmdbid INTEGER,f_title TEXT,f_media_type TEXT,f_year INTEGER,f_season INTEGER,FOREIGN KEY(owner) REFERENCES extraction_traces(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX trace_metadata_root ON trace_metadata(root);
CREATE TABLE item_entries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_tmdbid INTEGER NOT NULL,f_type TEXT NOT NULL,f_title TEXT NOT NULL,f_original_title TEXT NOT NULL,f_year INTEGER NOT NULL,f_overview TEXT NOT NULL,f_date TEXT NOT NULL,f_poster_path TEXT NOT NULL,f_backdrop_path TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES workspace_items(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_root ON item_entries(root);
CREATE TABLE item_entries_genres(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_entries(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_genres_root ON item_entries_genres(root);
CREATE TABLE item_entries_countries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_entries(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_countries_root ON item_entries_countries(root);
CREATE TABLE item_entries_cast(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_role TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES item_entries(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES recognitions(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX item_entries_cast_root ON item_entries_cast(root);
CREATE TABLE runs(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_title TEXT NOT NULL,f_mode TEXT NOT NULL,f_state TEXT NOT NULL,f_created TEXT NOT NULL,f_error TEXT NOT NULL,f_completed INTEGER NOT NULL,f_total INTEGER NOT NULL,f_undo INTEGER NOT NULL,f_batch_id TEXT NOT NULL,f_version INTEGER NOT NULL,f_recognition_id TEXT NOT NULL,f_purpose TEXT NOT NULL);
CREATE TABLE run_mappings(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_path TEXT NOT NULL,f_run_id TEXT NOT NULL,f_source TEXT NOT NULL,f_type TEXT NOT NULL,f_tmdbid INTEGER NOT NULL,f_season INTEGER NOT NULL,f_state TEXT NOT NULL,f_identity TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_work_dir TEXT NOT NULL,f_season_dir TEXT NOT NULL,f_movie_prefix INTEGER NOT NULL,f_layout_manual INTEGER NOT NULL,FOREIGN KEY(owner) REFERENCES runs(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX run_mappings_root ON run_mappings(root);
CREATE TABLE media_mappings(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_path TEXT NOT NULL,f_run_id TEXT NOT NULL,f_source TEXT NOT NULL,f_type TEXT NOT NULL,f_tmdbid INTEGER NOT NULL,f_season INTEGER NOT NULL,f_state TEXT NOT NULL,f_identity TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_work_dir TEXT NOT NULL,f_season_dir TEXT NOT NULL,f_movie_prefix INTEGER NOT NULL,f_layout_manual INTEGER NOT NULL);
CREATE TABLE workspace_originals(owner TEXT PRIMARY KEY REFERENCES workspace_items(k) ON DELETE CASCADE,root TEXT NOT NULL REFERENCES recognitions(id) ON DELETE CASCADE,f_path TEXT NOT NULL,f_run_id TEXT NOT NULL,f_source TEXT NOT NULL,f_type TEXT NOT NULL,f_tmdbid INTEGER NOT NULL,f_season INTEGER NOT NULL,f_state TEXT NOT NULL,f_identity TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_work_dir TEXT NOT NULL,f_season_dir TEXT NOT NULL,f_movie_prefix INTEGER NOT NULL,f_layout_manual INTEGER NOT NULL);
CREATE INDEX workspace_originals_root ON workspace_originals(root);
CREATE TABLE workspace_original_episodes(owner TEXT NOT NULL REFERENCES workspace_originals(owner) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,PRIMARY KEY(owner,position));
CREATE TABLE run_originals(owner TEXT PRIMARY KEY REFERENCES run_mappings(k) ON DELETE CASCADE,root TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE,f_path TEXT NOT NULL,f_run_id TEXT NOT NULL,f_source TEXT NOT NULL,f_type TEXT NOT NULL,f_tmdbid INTEGER NOT NULL,f_season INTEGER NOT NULL,f_state TEXT NOT NULL,f_identity TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_work_dir TEXT NOT NULL,f_season_dir TEXT NOT NULL,f_movie_prefix INTEGER NOT NULL,f_layout_manual INTEGER NOT NULL);
CREATE INDEX run_originals_root ON run_originals(root);
CREATE TABLE run_original_episodes(owner TEXT NOT NULL REFERENCES run_originals(owner) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,PRIMARY KEY(owner,position));
CREATE TABLE operations(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL,f_id INTEGER NOT NULL,f_kind TEXT NOT NULL,f_source TEXT NOT NULL,f_target TEXT NOT NULL,f_mode TEXT NOT NULL,f_size INTEGER NOT NULL,f_m_time INTEGER NOT NULL,f_content BLOB,f_url TEXT NOT NULL,f_convert_jpeg INTEGER NOT NULL,f_status TEXT NOT NULL,f_error TEXT NOT NULL,f_hash TEXT NOT NULL,f_temp TEXT NOT NULL,f_replace_hold TEXT NOT NULL,f_remove_hold TEXT NOT NULL,f_source_remove_hold TEXT NOT NULL,f_identity TEXT NOT NULL,f_source_identity TEXT NOT NULL,f_replace INTEGER NOT NULL,f_replace_identity TEXT NOT NULL,f_replace_size INTEGER NOT NULL,f_replace_m_time INTEGER NOT NULL,f_owner TEXT NOT NULL,f_reused INTEGER NOT NULL,undo_parent TEXT REFERENCES operations(k) ON DELETE CASCADE,FOREIGN KEY(owner) REFERENCES runs(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX operations_root ON operations(root);
CREATE TABLE operation_owners(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES operations(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES runs(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX operation_owners_root ON operation_owners(root);
CREATE TABLE extraction_traces(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,f_path TEXT NOT NULL,f_root TEXT NOT NULL,f_workspace_id TEXT NOT NULL,f_status TEXT NOT NULL,f_started_at TEXT NOT NULL,f_finished_at TEXT NOT NULL,f_error TEXT NOT NULL);
CREATE TABLE execution_queue(position INTEGER PRIMARY KEY AUTOINCREMENT,run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),purpose TEXT NOT NULL CHECK(purpose IN ('organize','scrape')));
CREATE INDEX execution_queue_purpose ON execution_queue(purpose,position);
CREATE INDEX runs_purpose ON runs(f_purpose,sequence);
CREATE INDEX runs_batch ON runs(f_batch_id,sequence);
CREATE INDEX runs_state ON runs(f_state);
CREATE INDEX recognitions_purpose ON recognitions(f_purpose,sequence);
CREATE INDEX runs_workspace ON runs(f_recognition_id);
CREATE INDEX operations_target ON operations(f_target,f_status);
CREATE INDEX run_mappings_path ON run_mappings(f_path);
CREATE INDEX media_mappings_work ON media_mappings(f_type,f_tmdbid);
CREATE INDEX extraction_trace_workspace ON extraction_traces(f_workspace_id);
CREATE INDEX extraction_trace_path ON extraction_traces(f_path);
CREATE UNIQUE INDEX operations_undo_parent ON operations(undo_parent) WHERE undo_parent IS NOT NULL;
CREATE TABLE confirmed_work_sets(id TEXT PRIMARY KEY);
CREATE TABLE snapshot_rules(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_id TEXT NOT NULL,f_name TEXT NOT NULL,f_description TEXT NOT NULL,f_target TEXT NOT NULL,f_source TEXT NOT NULL,f_order INTEGER NOT NULL,f_enabled INTEGER NOT NULL,f_kind TEXT NOT NULL,f_stage TEXT NOT NULL,f_config_code TEXT NOT NULL,f_config_params TEXT,f_config_pattern TEXT NOT NULL,f_config_capture TEXT NOT NULL,f_config_value TEXT,FOREIGN KEY(owner) REFERENCES extraction_traces(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX snapshot_rules_root ON snapshot_rules(root);
CREATE TABLE snapshot_rule_examples(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_root TEXT NOT NULL,f_expected TEXT,FOREIGN KEY(owner) REFERENCES snapshot_rules(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES extraction_traces(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE TABLE snapshot_rule_examples_paths(owner TEXT NOT NULL REFERENCES snapshot_rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE TABLE snapshot_rule_examples_targets(owner TEXT NOT NULL REFERENCES snapshot_rule_examples(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,PRIMARY KEY(owner,position));
CREATE INDEX snapshot_rule_examples_root ON snapshot_rule_examples(root);
CREATE TABLE confirmed_works(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position=0),f_tmdbid INTEGER NOT NULL,f_type TEXT NOT NULL,f_title TEXT NOT NULL,f_original_title TEXT NOT NULL,f_year INTEGER NOT NULL,f_overview TEXT NOT NULL,f_date TEXT NOT NULL,f_poster_path TEXT NOT NULL,f_backdrop_path TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES confirmed_work_sets(id) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES confirmed_work_sets(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX confirmed_works_root ON confirmed_works(root);
CREATE TABLE confirmed_works_genres(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES confirmed_works(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES confirmed_work_sets(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX confirmed_works_genres_root ON confirmed_works_genres(root);
CREATE TABLE confirmed_works_countries(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES confirmed_works(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES confirmed_work_sets(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX confirmed_works_countries_root ON confirmed_works_countries(root);
CREATE TABLE confirmed_works_cast(k TEXT PRIMARY KEY,root TEXT NOT NULL,owner TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),f_name TEXT NOT NULL,f_role TEXT NOT NULL,FOREIGN KEY(owner) REFERENCES confirmed_works(k) ON DELETE CASCADE,FOREIGN KEY(root) REFERENCES confirmed_work_sets(id) ON DELETE CASCADE,UNIQUE(owner,position));
CREATE INDEX confirmed_works_cast_root ON confirmed_works_cast(root);
CREATE TABLE mapping_works(owner TEXT PRIMARY KEY REFERENCES media_mappings(id) ON DELETE CASCADE,work_id TEXT NOT NULL REFERENCES confirmed_work_sets(id));
CREATE TABLE run_mapping_works(owner TEXT PRIMARY KEY REFERENCES run_mappings(k) ON DELETE CASCADE,work_id TEXT NOT NULL REFERENCES confirmed_work_sets(id));
CREATE TABLE workspace_original_works(owner TEXT PRIMARY KEY REFERENCES workspace_originals(owner) ON DELETE CASCADE,work_id TEXT NOT NULL REFERENCES confirmed_work_sets(id));
CREATE TABLE run_original_works(owner TEXT PRIMARY KEY REFERENCES run_originals(owner) ON DELETE CASCADE,work_id TEXT NOT NULL REFERENCES confirmed_work_sets(id));
CREATE TABLE extraction_snapshots(id TEXT PRIMARY KEY REFERENCES extraction_traces(id) ON DELETE CASCADE,digest TEXT NOT NULL);
CREATE TABLE snapshot_context(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),context_root TEXT NOT NULL,source_boundary TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_context_root ON snapshot_context(root);
CREATE TABLE snapshot_paths(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_context(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_paths_root ON snapshot_paths(root);
CREATE TABLE snapshot_targets(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_context(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_targets_root ON snapshot_targets(root);
CREATE TABLE snapshot_tree(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),path TEXT NOT NULL,parent TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_tree_root ON snapshot_tree(root);
CREATE TABLE snapshot_tree_files(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_tree(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_tree_files_root ON snapshot_tree_files(root);
CREATE TABLE snapshot_documents(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),file_id TEXT NOT NULL,path TEXT NOT NULL,directory TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_documents_root ON snapshot_documents(root);
CREATE TABLE snapshot_sources(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_documents(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),id TEXT NOT NULL,kind TEXT NOT NULL,text TEXT NOT NULL,depth INTEGER NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_sources_root ON snapshot_sources(root);
CREATE TABLE snapshot_tokens(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_documents(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),id TEXT NOT NULL,source_id TEXT NOT NULL,parent_id TEXT,kind TEXT NOT NULL,text TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_tokens_root ON snapshot_tokens(root);
CREATE TABLE snapshot_candidates(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_documents(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),id TEXT NOT NULL,rule_id TEXT NOT NULL,role TEXT NOT NULL,value TEXT NOT NULL,strength TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_candidates_root ON snapshot_candidates(root);
CREATE TABLE snapshot_spans(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_candidates(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),source_id TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_spans_root ON snapshot_spans(root);
CREATE TABLE snapshot_files(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),file_id TEXT NOT NULL,path TEXT NOT NULL,tmdb_id INTEGER,title TEXT,media_type TEXT,year INTEGER,season INTEGER,UNIQUE(owner,position));
CREATE INDEX snapshot_files_root ON snapshot_files(root);
CREATE TABLE snapshot_episodes(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_files(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),value INTEGER NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_episodes_root ON snapshot_episodes(root);
CREATE TABLE snapshot_decisions(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_files(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),target TEXT NOT NULL,reason TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_decisions_root ON snapshot_decisions(root);
CREATE TABLE snapshot_references(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES snapshot_decisions(k) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),file_id TEXT NOT NULL,candidate_id TEXT NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_references_root ON snapshot_references(root);
CREATE TABLE snapshot_diagnostics(k TEXT PRIMARY KEY,root TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,owner TEXT NOT NULL REFERENCES extraction_traces(id) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>=0),stage TEXT NOT NULL,file_id TEXT NOT NULL,rule_id TEXT NOT NULL,message TEXT NOT NULL,line INTEGER NOT NULL,column INTEGER NOT NULL,UNIQUE(owner,position));
CREATE INDEX snapshot_diagnostics_root ON snapshot_diagnostics(root);
`
